            let w = unsafe { S::eq_mask(v, 0x3d) & lv };
            r_m_pair_byte_3d[q % RING] = w;
            // class pair_byte_21
            let w = unsafe { S::eq_mask(v, 0x21) & lv };
            r_m_pair_byte_21[q % RING] = w;
            // class pair_byte_3c
            let w = unsafe { S::eq_mask(v, 0x3c) & lv };
            r_m_pair_byte_3c[q % RING] = w;
