            // (prev(t_lex) & ~rbrace) & ~lf
            let w = (r_m_t_lex[q % RING] << 1 | r_m_t_lex[(q + RING - 1) % RING] >> 63) & lv & (!r_m_rbrace[q % RING] & lv) & (!r_m_lf[q % RING] & lv);
            r_t2[q % RING] = w;
