            let w = r_m_rbrace[q % RING] & ((r_m_t_lex[q % RING] << 1 | r_m_t_lex[(q + RING - 1) % RING] >> 63) & lv | (r_m_t_body[q % RING] << 1 | r_m_t_body[(q + RING - 1) % RING] >> 63) & lv);
